CREATE INDEX "auth_permission_content_type_id_2f476e4b" ON "auth_permission" ("content_type_id");
CREATE INDEX "django_session_expire_date_a5c62663" ON "django_session" ("expire_date");
CREATE INDEX "homestay_room_homestay_id_a21c6a8a" ON "homestay_room" ("homestay_id");
CREATE INDEX "homestay_booking_homestay_id_504c4b8e" ON "homestay_booking" ("homestay_id");
CREATE INDEX "homestay_booking_room_id_5f06a126" ON "homestay_booking" ("room_id");
CREATE INDEX "homestay_review_homestay_id_55283e2e" ON "homestay_review" ("homestay_id");
